"""Production registration/dispatch/session/policy against a queued fake host, not native proof."""
from pathlib import Path
import subprocess,tempfile,hashlib
root=Path(__file__).resolve().parent.parent
source=root/'src/titlebar.rs'
command=source.read_text().split('#[cfg(target_os = "macos")]')[0].replace('#[tauri::command]','')
host='\n#![allow(dead_code,unused_imports)]\nextern crate self as tauri;\nuse std::{sync::{Arc,Mutex,atomic::{AtomicBool,Ordering}},future::Future,pin::Pin,task::{Context,Poll,Waker},any::Any};\npub mod async_runtime {\n pub struct Sender<T>(std::sync::mpsc::SyncSender<T>);pub struct Receiver<T>(std::sync::mpsc::Receiver<T>);\n pub fn channel<T>(size:usize)->(Sender<T>,Receiver<T>){let(s,r)=std::sync::mpsc::sync_channel(size);(Sender(s),Receiver(r))}\n impl<T> Sender<T>{pub fn try_send(&self,v:T)->Result<(),std::sync::mpsc::TrySendError<T>>{self.0.try_send(v)}}\n impl<T> Receiver<T>{pub async fn recv(&mut self)->Option<T>{std::future::poll_fn(|_|match self.0.try_recv(){Ok(v)=>std::task::Poll::Ready(Some(v)),Err(std::sync::mpsc::TryRecvError::Empty)=>std::task::Poll::Pending,Err(_)=>std::task::Poll::Ready(None)}).await}}\n}\nstruct ConfigWindow {label:String,minimizable:bool,maximizable:bool}\nstruct AppConfig {windows:Vec<ConfigWindow>}\nstruct Config {app:AppConfig}\nstruct Host {registry:titlebar::TitlebarState,queue:Mutex<Vec<Box<dyn FnOnce()+Send>>>,config:Config,queue_error:AtomicBool,state_available:AtomicBool}\nimpl Host {\n fn new()->Arc<Self>{Arc::new(Self{registry:Default::default(),queue:Default::default(),config:Config{app:AppConfig{windows:vec![ConfigWindow{label:"main".into(),minimizable:true,maximizable:true}]}},queue_error:AtomicBool::new(false),state_available:AtomicBool::new(true)})}\n fn config(&self)->&Config{&self.config}\n fn drain(&self){let q=std::mem::take(&mut *self.queue.lock().unwrap());for work in q{ON_UI.with(|v|v.set(true));work();ON_UI.with(|v|v.set(false));}}\n}\npub enum WindowEvent{Destroyed,CloseRequested}\npub struct State<\'a,T>(&\'a T);impl<T> State<\'_,T>{pub fn inner(&self)->&T{self.0}}\npub trait Manager{fn try_state<T:Any>(&self)->Option<State<\'_,T>>;}\n#[derive(Clone)]pub struct WebviewWindow(Arc<Window>);\nstruct Window{label:String,id:usize,host:Arc<Host>,alive:AtomicBool,listeners:Mutex<Vec<Box<dyn Fn(&WindowEvent)+Send>>>,actions:Mutex<Vec<(titlebar_session::Capabilities,&\'static str)>>}\nimpl WebviewWindow {\n fn new(host:&Arc<Host>,label:&str,id:usize)->Self{Self(Arc::new(Window{label:label.into(),id,host:host.clone(),alive:AtomicBool::new(true),listeners:Default::default(),actions:Default::default()}))}\n fn label(&self)->&str{&self.0.label}fn app_handle(&self)->&Host{&self.0.host}\n fn run_on_main_thread(&self,run:impl FnOnce()+Send+\'static)->Result<(),String>{if self.0.host.queue_error.load(Ordering::Relaxed){return Err("queue unavailable".into())}self.0.host.queue.lock().unwrap().push(Box::new(run));Ok(())}\n fn on_window_event(&self,run:impl Fn(&WindowEvent)+Send+\'static){self.0.listeners.lock().unwrap().push(Box::new(run))}\n fn destroy(&self){self.0.alive.store(false,Ordering::Relaxed);for f in self.0.listeners.lock().unwrap().iter(){f(&WindowEvent::Destroyed)}}\n}\nimpl Manager for WebviewWindow{fn try_state<T:Any>(&self)->Option<State<\'_,T>>{if !self.0.host.state_available.load(Ordering::Relaxed){return None}Some(State((&self.0.host.registry as &dyn Any).downcast_ref().unwrap()))}}\nthread_local!{static ON_UI:std::cell::Cell<bool>=const{std::cell::Cell::new(false)};}\nfn poll<F:Future>(future:Pin<&mut F>)->Poll<F::Output>{future.poll(&mut Context::from_waker(Waker::noop()))}\nconst NORMAL:titlebar_session::Capabilities=titlebar_session::Capabilities{minimizable:true,maximizable:true};\nfn registered(label:&str)->(Arc<Host>,WebviewWindow){let h=Host::new();let w=WebviewWindow::new(&h,label,10);titlebar::register(&w,NORMAL).unwrap();h.drain();(h,w)}\n'
native_fake='\nfn native_identity(w:&crate::WebviewWindow)->Result<usize,String>{assert!(crate::ON_UI.with(|v|v.get()));if !w.0.alive.load(crate::Ordering::Relaxed){return Err("destroyed dispatcher".into())}Ok(w.0.id)}\nfn perform(w:&crate::WebviewWindow,c:Capabilities,g:Gesture)->Result<(),String>{assert!(crate::ON_UI.with(|v|v.get()));w.0.actions.lock().unwrap().push((c,match g{Gesture::Drag=>"drag",Gesture::DoubleClick=>"double"}));Ok(())}\n'
tests='\n#[test]fn main_waits_for_ui_and_never_acts_inline(){let(h,w)=registered("main");let mut f=Box::pin(titlebar::native_titlebar_double_click(w.clone()));assert!(poll(f.as_mut()).is_pending());assert!(w.0.actions.lock().unwrap().is_empty());h.drain();assert!(matches!(poll(f.as_mut()),Poll::Ready(Ok(()))));assert_eq!(*w.0.actions.lock().unwrap(),vec![(NORMAL,"double")]);}\n#[test]fn unknown_window_rejected_before_ui_schedule(){let h=Host::new();let w=WebviewWindow::new(&h,"other",1);let mut f=Box::pin(titlebar::native_titlebar_drag(w));assert!(matches!(poll(f.as_mut()),Poll::Ready(Err(_))));assert!(h.queue.lock().unwrap().is_empty());}\n#[test]fn dynamic_window_uses_own_capabilities_not_main(){let h=Host::new();let w=WebviewWindow::new(&h,"test-window-2",2);let caps=titlebar_session::Capabilities{minimizable:true,maximizable:false};assert!(titlebar::register_configured(&w).is_err());titlebar::register(&w,caps).unwrap();h.drain();let mut f=Box::pin(titlebar::native_titlebar_double_click(w.clone()));assert!(poll(f.as_mut()).is_pending());h.drain();assert!(matches!(poll(f.as_mut()),Poll::Ready(Ok(()))));assert_eq!(*w.0.actions.lock().unwrap(),vec![(caps,"double")]);}\n#[test]fn configured_main_uses_exact_entry(){let h=Host::new();let w=WebviewWindow::new(&h,"main",2);titlebar::register_configured(&w).unwrap();h.drain();assert_eq!(h.registry.get("main").unwrap().capabilities,NORMAL);}\n#[test]fn queued_gesture_rejected_after_destroy(){let(h,w)=registered("main");let mut f=Box::pin(titlebar::native_titlebar_drag(w.clone()));assert!(poll(f.as_mut()).is_pending());w.destroy();h.drain();assert!(matches!(poll(f.as_mut()),Poll::Ready(Err(_))));assert!(w.0.actions.lock().unwrap().is_empty());}\n#[test]fn queued_gesture_never_targets_reopened_same_label(){let(h,old)=registered("main");let mut f=Box::pin(titlebar::native_titlebar_double_click(old.clone()));assert!(poll(f.as_mut()).is_pending());let new=WebviewWindow::new(&h,"main",20);titlebar::register(&new,NORMAL).unwrap();old.destroy();h.drain();assert!(matches!(poll(f.as_mut()),Poll::Ready(Err(_))));assert!(old.0.actions.lock().unwrap().is_empty());assert!(new.0.actions.lock().unwrap().is_empty());assert!(h.registry.get("main").unwrap().owns(20));}\n#[test]fn old_incoming_command_after_reopen_fails_identity_even_before_destroy(){let(h,old)=registered("main");let new=WebviewWindow::new(&h,"main",20);titlebar::register(&new,NORMAL).unwrap();h.drain();let mut f=Box::pin(titlebar::native_titlebar_double_click(old.clone()));assert!(poll(f.as_mut()).is_pending());h.drain();assert!(matches!(poll(f.as_mut()),Poll::Ready(Err(_))));assert!(old.0.actions.lock().unwrap().is_empty());}\n#[test]fn late_old_destroy_cannot_retire_new_session(){let(h,old)=registered("main");let new=WebviewWindow::new(&h,"main",20);titlebar::register(&new,NORMAL).unwrap();old.destroy();h.drain();let mut f=Box::pin(titlebar::native_titlebar_drag(new.clone()));assert!(poll(f.as_mut()).is_pending());h.drain();assert!(matches!(poll(f.as_mut()),Poll::Ready(Ok(()))));assert_eq!(*new.0.actions.lock().unwrap(),vec![(NORMAL,"drag")]);}\n#[test]fn pending_registration_cannot_bind_replacement(){let h=Host::new();let old=WebviewWindow::new(&h,"main",10);titlebar::register(&old,NORMAL).unwrap();let new=WebviewWindow::new(&h,"main",20);titlebar::register(&new,NORMAL).unwrap();h.drain();assert!(h.registry.get("main").unwrap().owns(20));assert!(!h.registry.get("main").unwrap().owns(10));}\n#[test]fn unbound_session_rejects_incoming_gesture(){let h=Host::new();let w=WebviewWindow::new(&h,"main",10);h.registry.register("main",NORMAL).unwrap();let mut f=Box::pin(titlebar::native_titlebar_drag(w.clone()));assert!(poll(f.as_mut()).is_pending());h.drain();assert!(matches!(poll(f.as_mut()),Poll::Ready(Err(_))));assert!(w.0.actions.lock().unwrap().is_empty());}\n#[test]fn queue_failure_propagates_without_action(){let(h,w)=registered("main");h.queue_error.store(true,Ordering::Relaxed);let mut f=Box::pin(titlebar::native_titlebar_drag(w.clone()));assert!(matches!(poll(f.as_mut()),Poll::Ready(Err(_))));assert!(w.0.actions.lock().unwrap().is_empty());}\n#[test]fn caller_cancellation_does_not_block_ui_callback(){let(h,w)=registered("main");let mut f=Box::pin(titlebar::native_titlebar_drag(w.clone()));assert!(poll(f.as_mut()).is_pending());drop(f);h.drain();assert_eq!(w.0.actions.lock().unwrap().len(),1);}\n#[test]fn native_policy_drag_full_sheet_capability_matrix(){for full in [false,true]{for sheet in [false,true]{for movable in [false,true]{assert_eq!(titlebar_policy::allows_drag(full,sheet,movable),!full&&!sheet&&movable);}}}}\n\n#[test]fn absent_mobile_state_returns_error_without_panic(){let h=Host::new();h.state_available.store(false,Ordering::Relaxed);let w=WebviewWindow::new(&h,"main",1);assert!(titlebar::register(&w,NORMAL).is_err());let mut f=Box::pin(titlebar::native_titlebar_drag(w));assert!(matches!(poll(f.as_mut()),Poll::Ready(Err(_))));assert!(h.queue.lock().unwrap().is_empty());}\n'
generated=host+'\nmod titlebar_session {\n'+source.with_name('titlebar_session.rs').read_text()+'\n}\nmod titlebar_policy {\n'+source.with_name('titlebar_policy.rs').read_text()+'\n}\nmod titlebar {\n'+command+native_fake+'\n}\n'+tests
with tempfile.TemporaryDirectory(prefix='titlebar-command-') as temporary:
 path=Path(temporary)/'host.rs';path.write_text(generated);binary=path.with_suffix('')
 subprocess.run(['rustup','run','1.94.1','rustc','--edition=2021','--test',str(path),'-o',str(binary)],check=True)
 for file in [source,source.with_name('titlebar_session.rs'),source.with_name('titlebar_policy.rs')]:print(file.name,hashlib.sha256(file.read_bytes()).hexdigest(),flush=True)
 raise SystemExit(subprocess.run([str(binary)]).returncode)
